using System.ComponentModel;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.Json;
using Microsoft.Data.Sqlite;
using Microsoft.Win32;
using Microsoft.Win32.SafeHandles;
namespace Arcoll.WinUI3.Services.PenteFino;
/// <summary>Somente IDs do relatório fresco e confirmado. Undo impede sobrescrever mudanças posteriores.</summary>
public sealed class FixEngine(ResultsStore store,PathPolicy policy,Func<Finding[],CancellationToken,Task<List<ActionResult>>>? external=null)
{
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]private static extern SafeFileHandle CreateFileW(string path,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
    [DllImport("kernel32.dll",SetLastError=true)]private static extern bool SetFileInformationByHandle(SafeFileHandle handle,int info,ref Disposition value,uint size);
    [StructLayout(LayoutKind.Sequential)]private struct Disposition{[MarshalAs(UnmanagedType.U1)]public bool Delete;}
    private static FileStream LockSource(string path){if(!OperatingSystem.IsWindows())return new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read);var handle=CreateFileW(path,0x80010000,1,IntPtr.Zero,3,0x08200000,IntPtr.Zero);if(handle.IsInvalid){handle.Dispose();throw new Win32Exception(Marshal.GetLastWin32Error(),"Arquivo em uso ou sem permissão.");}return new FileStream(handle,FileAccess.Read);}
    private static void RemoveLocked(FileStream stream,string path){if(OperatingSystem.IsWindows()){var data=new Disposition{Delete=true};if(!SetFileInformationByHandle(stream.SafeFileHandle,4,ref data,(uint)Marshal.SizeOf<Disposition>()))throw new Win32Exception(Marshal.GetLastWin32Error(),"Quarentena não autorizada pelo Windows.");}else File.Delete(path);}
    private static string ReadHash(Stream stream){var hash=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(stream)).ToLowerInvariant();stream.Position=0;return hash;}
    private void ValidateFile(Finding item){if(!policy.Allows(item.Path,item.Rule))throw new InvalidOperationException("Arquivo fora das regras permitidas.");var rule=policy.Rules.Single(x=>x.Id==item.Rule);if(PathPolicy.BrowserOpen(rule.Browser))throw new IOException("Feche o navegador antes de corrigir/restaurar o perfil.");if(item.Rule.EndsWith("-profile")&&Path.GetFileName(item.Path)is not("History" or "Cookies"))throw new IOException("Arquivo fora da lista do perfil.");if(item.Rule.EndsWith("-network")&&Path.GetFileName(item.Path)!="Cookies")throw new IOException("Arquivo de rede do navegador não permitido.");if(item.Rule.EndsWith("-firefox")&&Path.GetFileName(item.Path)!="cookies.sqlite")throw new IOException("Banco do Firefox não permitido.");if(File.Exists(item.Path+"-wal")&&new FileInfo(item.Path+"-wal").Length>0)throw new IOException("Banco com transações pendentes.");}
    public async Task<FixReport> FixAsync(ScanReport report,string[] selected,CancellationToken ct,IProgress<FixProgressState>? progress=null,bool createRestorePoint=false){if(!store.VerifyAudit())throw new InvalidDataException("A auditoria precisa de revisão; nenhuma correção foi iniciada.");if(report.Cancelled||DateTimeOffset.UtcNow-report.At>TimeSpan.FromMinutes(20))throw new InvalidOperationException("Faça uma nova análise antes de corrigir.");var all=report.Modules.SelectMany(x=>x.Items).ToDictionary(x=>x.Id);if(selected.Length==0||selected.Length>all.Count||selected.Distinct().Count()!=selected.Length||selected.Any(id=>!all.TryGetValue(id,out var f)||!f.CanFix))throw new InvalidOperationException("Seleção de correção inválida.");var items=selected.Select(x=>all[x]).ToArray();var session=Guid.NewGuid().ToString("N");var results=new List<ActionResult>();var cancelled=false;var succeeded=0;var failed=0;var total=items.Sum(i=>Math.Max(1,i.Quantity));int Completed()=>results.Sum(r=>Math.Max(1,all[r.Id].Quantity));progress?.Report(new(0,total,null,"waiting",new Dictionary<string,bool>(),succeeded,failed));
        if(createRestorePoint){if(!IsElevated())throw new InvalidOperationException("Para criar o ponto de restauração, abra o gestor como administrador. Nenhum ajuste foi aplicado.");await RestorePointAsync(ct);}
        store.Audit("fix-confirmed",new{session,report.Id,ids=selected,recoveryCopies=false,createRestorePoint});
        foreach(var batch in items.GroupBy(x=>x.Kind is "clean-category" or "tool-registry"?x.Kind:x.Kind=="cookies"?x.Path:x.Id,StringComparer.OrdinalIgnoreCase)){
            if(ct.IsCancellationRequested){cancelled=true;break;}var list=batch.ToArray();progress?.Report(new(Completed(),total,list[0].Id,"running",new Dictionary<string,bool>(),succeeded,failed));try{if(list[0].Kind is "clean-category" or "tool-registry"){
                if(external is null)throw new InvalidOperationException("Motor de análise indisponível.");var applied=await external(list,ct);if(applied.Count!=list.Length||applied.Any(r=>!list.Any(i=>i.Id==r.Id))||applied.DistinctBy(r=>r.Id).Count()!=list.Length)throw new InvalidDataException("Resultado do motor inválido.");results.AddRange(applied);succeeded+=applied.Where(r=>r.Ok).Sum(r=>Math.Max(1,all[r.Id].Quantity));failed+=applied.Where(r=>!r.Ok).Sum(r=>Math.Max(1,all[r.Id].Quantity));continue;
            }if(list[0].Kind=="file")await QuarantineAsync(session,list[0],ct);else if(list[0].Kind=="cookies")await CookiesAsync(session,list,ct);else if(list[0].Kind is "startup" or "registry")RegistryFix(session,list[0]);else throw new InvalidOperationException("Ação não suportada.");results.AddRange(list.Select(x=>new ActionResult(x.Id,true,"Correção aplicada sem cópia de recuperação.")));succeeded+=list.Sum(i=>Math.Max(1,i.Quantity));}
            catch(OperationCanceledException){cancelled=true;break;}
            catch(Exception error){store.Audit("fix-failed",new{session,ids=list.Select(x=>x.Id),error=error.Message});results.AddRange(list.Select(x=>new ActionResult(x.Id,false,error.Message)));failed+=list.Sum(i=>Math.Max(1,i.Quantity));}finally{progress?.Report(new(Completed(),total,null,"updated",new Dictionary<string,bool>(),succeeded,failed));}
        }
        store.Audit("fix-finished",new{session,cancelled,results});return new(session,DateTimeOffset.UtcNow,results,cancelled);
    }
    private Task QuarantineAsync(string session,Finding item,CancellationToken ct){
        ct.ThrowIfCancellationRequested();ValidateFile(item);using var input=LockSource(item.Path);var info=new FileInfo(item.Path);
        if(info.Length!=item.Bytes||info.LastWriteTimeUtc.Ticks!=item.ModifiedTicks)throw new IOException("Arquivo mudou desde a análise; faça nova verificação.");
        var hash=ReadHash(input);store.Audit("delete-prepare",new{session,item.Id,hash});ct.ThrowIfCancellationRequested();ValidateFile(item);RemoveLocked(input,item.Path);store.Audit("delete-applied",new{session,item.Id,hash});return Task.CompletedTask;
    }
    private async Task CookiesAsync(string session,Finding[] items,CancellationToken ct){var first=items[0];ValidateFile(first);var file=new FileInfo(first.Path);if(items.Any(x=>x.Path!=first.Path||x.Kind!="cookies"||x.ModifiedTicks!=first.ModifiedTicks)||file.LastWriteTimeUtc.Ticks!=first.ModifiedTicks)throw new IOException("Banco mudou desde a análise; examine novamente.");string hash;using(var source=LockSource(first.Path))hash=ReadHash(source);
        store.Audit("cookies-prepare",new{session,ids=items.Select(x=>x.Id),hash});ct.ThrowIfCancellationRequested();ValidateFile(first);
        // Revalida imediatamente antes da transação. A conexão requer bloqueio exclusivo do banco.
        using(var db=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=first.Path,Mode=SqliteOpenMode.ReadWrite,Pooling=false,DefaultTimeout=1}.ToString())){db.Open();using var setup=db.CreateCommand();setup.CommandText="PRAGMA locking_mode=EXCLUSIVE;";setup.ExecuteNonQuery();using var transaction=db.BeginTransaction(deferred:false);if(ResultsStore.FileHash(first.Path,true)!=hash)throw new IOException("Banco alterado após o backup.");foreach(var item in items){ct.ThrowIfCancellationRequested();if(policy.TrustedCookie(item.Selector,store.LoadSettings().TrustedCookies))throw new IOException("Domínio passou a ser confiável; refaça a análise.");using var q=db.CreateCommand();q.Transaction=transaction;q.CommandText=first.ValueKind=="firefox"?"DELETE FROM moz_cookies WHERE host=$host":"DELETE FROM cookies WHERE host_key=$host";q.Parameters.AddWithValue("$host",item.Selector);q.ExecuteNonQuery();}transaction.Commit();using var checkpoint=db.CreateCommand();checkpoint.CommandText="PRAGMA wal_checkpoint(TRUNCATE)";checkpoint.ExecuteNonQuery();}
        var after=ResultsStore.FileHash(first.Path);store.Audit("cookies-applied",new{session,ids=items.Select(x=>x.Id),after});await Task.CompletedTask;
    }
    private void RegistryFix(string session,Finding item){if(!OperatingSystem.IsWindows()||!RegistryValues.Allowed(item.Path,item.Kind))throw new InvalidOperationException("Alvo de registro fora da lista permitida.");var (root,path,name)=RegistryValues.Open(item.Path,true);using(root){using var key=root.OpenSubKey(path,true)??throw new IOException("Chave não encontrada.");if(!key.GetValueNames().Contains(name))throw new IOException("Valor já não existe.");var kind=key.GetValueKind(name);var value=key.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames);if(RegistryValues.Encode(value,kind)!=item.Expected)throw new IOException("Registro alterado desde a análise.");var target=item.Path;byte[]? disabled=null;
            if(item.Kind=="startup"){var originalParts=item.Path.Split('|',4);var approval=@"Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\"+(originalParts[0]=="LocalMachine"&&originalParts[1]=="Registry32"?"Run32":"Run");var parts=item.Path.Split('|',4);target=string.Join("|",parts[0],parts[1],approval,name);disabled=new byte[12];disabled[0]=3;BitConverter.GetBytes(DateTime.UtcNow.ToFileTimeUtc()).CopyTo(disabled,4);
            }
            store.Audit("registry-prepare",new{session,item.Id,target});
            if(item.Kind=="startup"){using var approved=root.CreateSubKey(target.Split('|',4)[2],true);approved.SetValue(name,disabled!,RegistryValueKind.Binary);approved.Flush();}else{key.DeleteValue(name,true);key.Flush();}
            store.Audit("registry-applied",new{session,item.Id,target});
        }}
    public async Task<List<ActionResult>> UndoAsync(string session,CancellationToken ct){if(!store.VerifyAudit())throw new InvalidDataException("A auditoria precisa de revisão; backups foram preservados para recuperação.");var results=new List<ActionResult>();foreach(var entry in store.UndoEntries().Where(x=>x.Session==session&&(x.State is "applied" or "prepared"))){
            ct.ThrowIfCancellationRequested();try{if(DateTimeOffset.UtcNow-entry.At>TimeSpan.FromDays(30))throw new IOException("Prazo de 30 dias expirado.");if(!System.Text.RegularExpressions.Regex.IsMatch(entry.Session,"^[a-f0-9]{32}$")||!PathPolicy.Inside(entry.Backup,store.LocalPath("backup",entry.Session)))throw new IOException("Backup fora da pasta da sessão.");PathPolicy.RejectLinks(entry.Backup);store.Audit("undo-prepare",new{entry.Id,entry.Target});
                if(entry.Kind is "file" or "cookies"){
                    var finding=JsonSerializer.Deserialize<Finding>(entry.BeforeValue)??throw new IOException("Manifesto inválido.");if(finding.Path!=entry.Target)throw new IOException("Manifesto não corresponde ao alvo.");ValidateFile(finding);if(ResultsStore.FileHash(entry.Backup)!=entry.BeforeHash)throw new IOException("Backup corrompido.");
                    if(File.Exists(entry.Target)){var current=ResultsStore.FileHash(entry.Target);if(current==entry.BeforeHash){store.Journal(entry with{State="undone"});results.Add(new(entry.Id,true,"Conteúdo original já presente."));continue;}if(entry.Kind!="cookies"||entry.AfterHash.Length==0||current!=entry.AfterHash)throw new IOException("Conflito: o alvo contém alterações posteriores. Nada foi sobrescrito.");
                        // Banco fechado e sem WAL: substituição atômica com cópia no próprio diretório.
                        using(var test=LockSource(entry.Target)){};
                    }
                    var destination=Path.GetDirectoryName(entry.Target)!;if(!Directory.Exists(destination))throw new IOException("Pasta original não existe; revisão manual necessária.");PathPolicy.RejectLinks(destination);var temp=Path.Combine(destination,".pentefino-undo-"+Guid.NewGuid().ToString("N"));try{await using(var source=new FileStream(entry.Backup,FileMode.Open,FileAccess.Read,FileShare.Read,65536,true))await using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None,65536,true)){await source.CopyToAsync(output,65536,ct);await output.FlushAsync(ct);output.Flush(true);}if(ResultsStore.FileHash(temp)!=entry.BeforeHash)throw new IOException("Restauração não passou pela verificação.");ct.ThrowIfCancellationRequested();ValidateFile(finding);if(entry.Kind=="cookies"){if(ResultsStore.FileHash(entry.Target)!=entry.AfterHash)throw new IOException("Conflito durante restauração.");File.Move(temp,entry.Target,true);}else File.Move(temp,entry.Target,false);File.SetLastWriteTimeUtc(entry.Target,new DateTime(finding.ModifiedTicks,DateTimeKind.Utc));}finally{if(File.Exists(temp))File.Delete(temp);}
                }else{
                    var parts=entry.Target.Split('|',4);if(parts.Length!=4||!(RegistryValues.Allowed(entry.Target,"registry")||entry.Kind=="startup"&&(parts[2]==@"Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run"||parts[2]==@"Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run32")))throw new IOException("Alvo de restauração fora da lista.");var (root,path,name)=RegistryValues.Open(entry.Target,true);using(root){using var key=root.OpenSubKey(path,true)??throw new IOException("Chave de restauração ausente.");var current=key.GetValueNames().Contains(name)?RegistryValues.Encode(key.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames),key.GetValueKind(name)):"";if(ResultsStore.Hash(current)!=entry.AfterHash){if(current==entry.BeforeValue){store.Journal(entry with{State="undone"});results.Add(new(entry.Id,true,"Registro original já presente."));continue;}throw new IOException("Registro mudou depois da correção; nada foi sobrescrito.");}if(entry.BeforeValue.Length==0)key.DeleteValue(name,false);else{var kind=Enum.Parse<RegistryValueKind>(entry.ValueKind);key.SetValue(name,RegistryValues.Decode(entry.BeforeValue,kind),kind);}key.Flush();}
                }
                store.Journal(entry with{State="undone"});store.Audit("undo-applied",new{entry.Id,entry.Target});results.Add(new(entry.Id,true,"Restaurado."));
            }catch(Exception error)when(error is not OperationCanceledException){store.Audit("undo-failed",new{entry.Id,error=error.Message});results.Add(new(entry.Id,false,error.Message));}
        }return results;
    }
    public void Expire(){foreach(var entry in store.UndoEntries().Where(x=>(x.State is "applied" or "undone")&&DateTimeOffset.UtcNow-x.At>TimeSpan.FromDays(30))){if(!System.Text.RegularExpressions.Regex.IsMatch(entry.Session,"^[a-f0-9]{32}$")||!PathPolicy.Inside(entry.Backup,store.LocalPath("backup",entry.Session)))continue;PathPolicy.RejectLinks(entry.Backup);store.Audit("backup-expire",new{entry.Id,entry.Backup});if(File.Exists(entry.Backup))File.Delete(entry.Backup);if(entry.Kind is "registry" or "startup"){var reg=Path.ChangeExtension(entry.Backup,".reg");PathPolicy.RejectLinks(reg);if(File.Exists(reg))File.Delete(reg);}store.Journal(entry with{State="expired"});}}
    private static bool IsElevated(){if(!OperatingSystem.IsWindows())return false;using var identity=System.Security.Principal.WindowsIdentity.GetCurrent();return new System.Security.Principal.WindowsPrincipal(identity).IsInRole(System.Security.Principal.WindowsBuiltInRole.Administrator);}
    private static async Task RestorePointAsync(CancellationToken ct){if(!OperatingSystem.IsWindows())throw new PlatformNotSupportedException("Ponto de restauração exige Windows.");var path=Path.Combine(Environment.SystemDirectory,@"WindowsPowerShell\v1.0\powershell.exe");var start=new ProcessStartInfo(path){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var arg in new[]{"-NoProfile","-NonInteractive","-Command","$ErrorActionPreference='Stop';$before=(Get-CimInstance -Namespace root/default -ClassName SystemRestore | Measure-Object SequenceNumber -Maximum).Maximum;$r=Invoke-CimMethod -Namespace root/default -ClassName SystemRestore -MethodName CreateRestorePoint -Arguments @{Description='Pente-Fino — antes da correção';RestorePointType=12;EventType=100};if($r.ReturnValue -ne 0){throw 'Ponto de restauração não confirmado'};$after=Get-CimInstance -Namespace root/default -ClassName SystemRestore | Where-Object { $_.SequenceNumber -gt $before -and $_.Description -eq 'Pente-Fino — antes da correção' };if(-not $after){throw 'Nenhum novo ponto de restauração foi confirmado'};Write-Output 'PENTEFINO_RESTORE_OK'"})start.ArgumentList.Add(arg);using var process=Process.Start(start)??throw new IOException("Ponto de restauração não iniciado.");var output=process.StandardOutput.ReadToEndAsync(ct);var error=process.StandardError.ReadToEndAsync(ct);using var timeout=CancellationTokenSource.CreateLinkedTokenSource(ct);timeout.CancelAfter(TimeSpan.FromSeconds(90));try{await process.WaitForExitAsync(timeout.Token);}catch{try{process.Kill(true);}catch(InvalidOperationException){}throw;}if(process.ExitCode!=0||!(await output).Contains("PENTEFINO_RESTORE_OK",StringComparison.Ordinal))throw new IOException("Correção interrompida: o Windows não confirmou o ponto de restauração. "+await error);}
}
